input.command:
mkdir -p src/db scripts
cat > .env.example <<'E'
# Postgres connection string (placeholder credentials)
DATABASE_URL=postgres://app_user:change-me@localhost:5432/app_db
E
cat > docker-compose.yml <<'E'
services:
  db:
    image: postgres:17
    environment:
      POSTGRES_USER: app_user
      POSTGRES_PASSWORD: change-me
      POSTGRES_DB: app_db
    ports:
      - "5432:5432"
    volumes:
      - pgdata:/var/lib/postgresql/data
volumes:
  pgdata:
E
cat > drizzle.config.ts <<'E'
import { defineConfig } from "drizzle-kit";

export default defineConfig({
  dialect: "postgresql",
  schema: "./src/db/schema.ts",
  out: "./drizzle",
  dbCredentials: { url: process.env.DATABASE_URL! },
});
E
cat > src/db/schema.ts <<'E'
import { date, integer, pgTable, text } from "drizzle-orm/pg-core";

export const users = pgTable("users", {
  id: integer().primaryKey().generatedAlwaysAsIdentity(),
  email: text().notNull().unique(),
  name: text().notNull(),
  createdAt: date("created_at", { mode: "string" }).notNull().defaultNow(),
});

export type UserRow = typeof users.$inferSelect;
export type NewUserRow = typeof users.$inferInsert;
E
cat > src/db/index.ts <<'E'
import { drizzle } from "drizzle-orm/postgres-js";
import postgres from "postgres";
import * as schema from "./schema";

const globalForDb = globalThis as unknown as { sql?: ReturnType<typeof postgres> };

function connect() {
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error("DATABASE_URL is not set (see .env.example)");
  return postgres(url);
}

// Reuse the connection across dev hot reloads.
const sql = (globalForDb.sql ??= connect());

export const db = drizzle(sql, { schema });
E
cat > src/lib/users.ts <<'E'
import { asc, eq } from "drizzle-orm";
import { db } from "@/db";
import { users, type UserRow } from "@/db/schema";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

function toUser(row: UserRow): User {
  return { ...row, id: String(row.id) };
}

export async function listUsers(): Promise<User[]> {
  const rows = await db.select().from(users).orderBy(asc(users.id));
  return rows.map(toUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  if (!/^\d+$/.test(id)) return undefined;
  const [row] = await db.select().from(users).where(eq(users.id, Number(id)));
  return row && toUser(row);
}

// TODO: there is no real session handling yet — the dashboard just picks the first user.
export async function getCurrentUser(): Promise<User | undefined> {
  const [row] = await db.select().from(users).orderBy(asc(users.id)).limit(1);
  return row && toUser(row);
}
E
cat > scripts/seed.ts <<'E'
import { db } from "../src/db";
import { users } from "../src/db/schema";

await db
  .insert(users)
  .values([
    { email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
    { email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
  ])
  .onConflictDoNothing({ target: users.email });

console.log("seeded");
process.exit(0);
E
npm pkg set scripts.db:generate="drizzle-kit generate" scripts.db:migrate="drizzle-kit migrate" scripts.db:seed="tsx --env-file=.env scripts/seed.ts"
sed -i '' 's#"db:migrate": "drizzle-kit migrate"#"db:migrate": "tsx --env-file=.env node_modules/drizzle-kit/bin.cjs migrate"#' package.json
npx drizzle-kit generate 2>&1 | tail -5; ls drizzle; npx tsc --noEmit && npm run lint 2>&1 | tail -5

